using System;
using System.Text.Json.Serialization;
using AmazonSwf.Core.Enum;

namespace AmazonSwf.Models.Enums;

/// <summary>
/// The cause of the failure. This information is generated by the system and can be useful for diagnostic purposes. If cause is set to OPERATION_NOT_PERMITTED, the decision failed because it lacked sufficient permissions. For details and example IAM policies, see Using IAM to Manage Access to Amazon SWF Workflows in the Amazon SWF Developer Guide.
/// </summary>
[JsonConverter(typeof(StringEnumConverter<Cause11>))]
public sealed record Cause11 : OpenStringEnum<Cause11>
{
    private Cause11(string value) : base(value)
    {
    }

    public static readonly Cause11 TimerIdAlreadyInUse = new("TIMER_ID_ALREADY_IN_USE");

    public static readonly Cause11 OpenTimersLimitExceeded = new("OPEN_TIMERS_LIMIT_EXCEEDED");

    public static readonly Cause11 TimerCreationRateExceeded = new("TIMER_CREATION_RATE_EXCEEDED");

    public static readonly Cause11 OperationNotPermitted = new("OPERATION_NOT_PERMITTED");

    public TResult Match<TResult>(Func<TResult> onTimerIdAlreadyInUse,
        Func<TResult> onOpenTimersLimitExceeded,
        Func<TResult> onTimerCreationRateExceeded,
        Func<TResult> onOperationNotPermitted,
        Func<string, TResult> otherwise) =>
        this switch
        {
            _ when this == TimerIdAlreadyInUse => onTimerIdAlreadyInUse(),
            _ when this == OpenTimersLimitExceeded => onOpenTimersLimitExceeded(),
            _ when this == TimerCreationRateExceeded => onTimerCreationRateExceeded(),
            _ when this == OperationNotPermitted => onOperationNotPermitted(),
            _ => otherwise(Value)
        };

    public void Match(Action onTimerIdAlreadyInUse,
        Action onOpenTimersLimitExceeded,
        Action onTimerCreationRateExceeded,
        Action onOperationNotPermitted,
        Action<string> otherwise)
    {
        if (this == TimerIdAlreadyInUse) onTimerIdAlreadyInUse();
        else if (this == OpenTimersLimitExceeded) onOpenTimersLimitExceeded();
        else if (this == TimerCreationRateExceeded) onTimerCreationRateExceeded();
        else if (this == OperationNotPermitted) onOperationNotPermitted();
        else otherwise(Value);
    }
}
